function metric(label,value,unit,note=''){return '<div class="color-metric"><span>'+esc(label)+'</span><strong>'+esc(value)+'</strong><p>'+esc(unit)+(note?' · '+esc(note):'')+'</p></div>';}
function cancelQuality(){serial++;if(busy&&worker){worker.terminate();worker=null;}busy=false;$('lighting-quality-run').disabled=false;quality=null;$('lighting-quality-output').hidden=true;$('lighting-quality-export').disabled=true;}
function clearPhoto(){photo=null;$('photo-export').disabled=true;$('photo-alpha-results').innerHTML='<tr><td colspan="5">Calculate again for the current spectrum and measurement.</td></tr>';$('photo-weighted-results').innerHTML='';$('photo-coverage').textContent='';}
function updateSource(detail){sourceName=detail.source;selected=detail.spectrum?core.prepare(detail.spectrum):null;cancelQuality();clearPhoto();device=null;$('led-results').innerHTML='';$('led-export').disabled=true;$('lighting-source').textContent=selected?sourceName+' · '+selected.points.length.toLocaleString()+' wavelengths · '+f(selected.lo,1)+'–'+f(selected.hi,1)+' nm · maximum visible sampling gap '+f(selected.gap,2)+' nm':'Current input is coordinates / temperature. Upload a spectrum to calculate rendering or biological weighting.';status('lighting-quality-status',selected?'Spectrum ready. Calculate to evaluate color rendition.':'A numerical spectrum is required; color coordinates alone do not specify rendering.');status('photo-status',selected?'Spectrum ready. Add a photopic measurement for absolute quantities, or calculate ratios alone.':'Select a numerical spectrum in the emission input above.');status('led-status','Measurements can be entered below. Calculate again after changing the spectrum.');}
