function needSpectrum(){if(!selected)throw Error('Select a numerical emission spectrum above. These quantities cannot be recovered from xy coordinates.');return selected;}
function makeWorker(){const w=new Worker('lighting-worker.js?v=20261116b');w.onmessage=({data})=>{if(data.type==='progress'){if(busy)status('lighting-quality-status',data.message);return;}if(data.id!==serial)return;busy=false;$('lighting-quality-run').disabled=false;if(data.type==='error'){status('lighting-quality-status','Calculation unavailable: '+data.error+' Check spectral coverage and the near-white domain. An internet connection is needed for the first engine load.',true);return;}quality=data.result;renderQuality();status('lighting-quality-status','Color rendition calculated with Colour 0.4.7. Source: '+sourceName+($('lighting-zero').checked?' · zero extension explicitly assumed.':'.'));};w.onerror=()=>{busy=false;$('lighting-quality-run').disabled=false;status('lighting-quality-status','The advanced engine could not load. Check your internet connection and try again; the CIE diagrams and basic efficiency calculations remain available.',true);w.terminate();worker=null;};return w;}
 $('lighting-quality-run').addEventListener('click',fail('lighting-quality-status',()=>{const s=needSpectrum(),zero=$('lighting-zero').checked;if(!core.covers(s,380,780,zero))throw Error('Supply the full 380–780 nm spectrum, or explicitly confirm zero emission outside the supplied interval.');if(s.gap>5.000001)throw Error('The visible sampling gap exceeds 5 nm. Upload more finely sampled data; interpolating a coarse file does not restore missing spectral detail.');const c=window.CIECore.cct(window.CIECore.spectrum(s.points).xy);if(!c.valid||c.temperature<2000||c.temperature>25000)throw Error('Rendering scores are reported for near-white spectra at 2000–25000 K and |Duv| ≤ 0.05. Saturated single-color emitters are outside this domain.');cancelQuality();busy=true;$('lighting-quality-run').disabled=true;status('lighting-quality-status','Preparing color-quality calculations…');if(!worker)worker=makeWorker();worker.postMessage({id:serial,payload:{points:s.points,zero}});}));
