 function photoLabels(){const kind=$('photo-kind').value,radiance=kind==='luminance'||kind==='radiance';$('photo-level-label').textContent={luminance:'Measured luminance / cd·m⁻²',illuminance:'Measured illuminance / lx',irradiance:'Measured irradiance over the uploaded interval / W·m⁻²',radiance:'Measured radiance over the uploaded interval / W·m⁻²·sr⁻¹'}[kind];$('photo-edi-heading').textContent=radiance?'Equivalent daylight luminance / cd·m⁻²':'Equivalent daylight illuminance / lx';$('photo-weight-heading').textContent=radiance?'α-opic radiance / W·m⁻²·sr⁻¹':'α-opic irradiance / W·m⁻²';}
